-- Partition by year
CREATE PARTITION FUNCTION pf_order_year (DATE)
AS RANGE RIGHT FOR VALUES ('2023-01-01', '2024-01-01', '2025-01-01');

CREATE PARTITION SCHEME ps_order_year
AS PARTITION pf_order_year
ALL TO ([PRIMARY]);

CREATE TABLE sales.large_orders (
    order_id    INT IDENTITY,
    order_date  DATE,
    customer_id INT,
    amount      MONEY
) ON ps_order_year(order_date);
